Title: HAL_UARTEx_ReceiveToIdle_DMA losing the last byte during reception.

Body:
init：
        HAL_UART_Init(&huart4)
        HAL_UART_RegisterRxEventCallback(&huart4, UARTEx_RxEventCallback);
        HAL_UART_RegisterCallback(&huart4, HAL_UART_TX_COMPLETE_CB_ID, UART_TxCompleteCallback);
        HAL_UART_RegisterCallback(&huart4, HAL_UART_ERROR_CB_ID, UART_ErrorCallback);

callback：
static void UARTEx_RxEventCallback(UART_HandleTypeDef *huart, uint16_t Size)
{
    if (huart == &huart4)
    {
        rx_len = Size;
        osSemaphoreRelease(rx_sem);
    }
}

static void UART_TxCompleteCallback(UART_HandleTypeDef *huart)
{
    if (huart == &huart4)
    {
        SET_BIT(huart4.Instance->CR1, USART_CR1_RE); 
        CLEAR_BIT(huart4.Instance->CR1, USART_CR1_TE);
    }
}

static void UART_ErrorCallback(UART_HandleTypeDef *huart)
{
    if (huart == &huart4)
    {
        HAL_UART_DMAStop(&huart4);
        __HAL_UNLOCK(huart);
        rx_len = 0;
        osSemaphoreRelease(rx_sem);
    }
}

run:
    CLEAR_BIT(huart4.Instance->CR1, USART_CR1_RE);
    SET_BIT(huart4.Instance->CR1, USART_CR1_TE); 
    HAL_StatusTypeDef status = HAL_UART_Transmit(&huart4, sdata, tlen, timeout);
    if (status != HAL_OK)
    {
        osMutexRelease(uartMutex);
        return 0; 
