    if (HAL_UARTEx_ReceiveToIdle_IT(&huart4, (uint8_t*)rxbuff, buffSize)!= HAL_OK)
    {
        osMutexRelease(uartMutex);
        return 0;
    }
    if (osSemaphoreAcquire(rx_sem, timeout) == osOK)
    { 
        if (rx_len > 0 && rdata != NULL)
        {
            rlen = rx_len;
            if (rlen > buffSize)
            {
                rlen = buffSize; 
            }
            for (uint16_t i = 0; i < rlen; i++)
            {
                rdata[i] = rxbuff[i]&0x7F;
            }
        }
        else
        {
            rlen = 0;
        }
    }

issue:
  stm32 send command: "012345678912345"
  received length(15) is ok: "012345678912345"
